From 9d6650e6672e77482f4643b539c9444442ba4fa1 Mon Sep 17 00:00:00 2001
From: Craig Barnes <Cr@igBarn.es>
Date: Tue, 31 Dec 2019 19:56:12 +0000
Subject: [PATCH] Call term_mode_init() properly when DTE_FORCE_TERMINFO is set

This fixes a bug that was introduced in commit
23daf151dc4ba9d32eeb3c45a215ed44f8c5423d.

diff --git a/src/terminal/terminal.c b/src/terminal/terminal.c
index f689f777..b6f52b20 100644
--- a/src/terminal/terminal.c
+++ b/src/terminal/terminal.c
@@ -84,6 +84,10 @@ void term_init(void)
         term_init_fail("'TERM' not set");
     }

+    if (!term_mode_init()) {
+        term_init_fail("tcgetattr: %s", strerror(errno));
+    }
+
     if (getenv("DTE_FORCE_TERMINFO")) {
         if (term_init_terminfo(term)) {
             return;
@@ -92,10 +96,6 @@ void term_init(void)
         }
     }

-    if (!term_mode_init()) {
-        term_init_fail("tcgetattr: %s", strerror(errno));
-    }
-
     switch (get_term_type(term)) {
     case TERM_XTERM:
         terminal = xterm;
-- 
2.25.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
Call term_mode_init() properly when DTE_FORCE_TERMINFO is set

This fixes a bug that was introduced in commit
23daf151dc4ba9d32eeb3c45a215ed44f8c5423d.

Here is the root cause:
The bug was caused by the improper placement of the `term_mode_init()` function call within the `term_init()` function. The function was originally called after checking the `DTE_FORCE_TERMINFO` environment variable, which could lead to a situation where terminal modes were not initialized correctly before attempting to use them, resulting in potential failures or undefined behavior.

Here is the patch:

 void term_init(void)
 {
     const char *term = getenv("TERM");
     if (term == NULL || term[0] == '\0') {
         term_init_fail("'TERM' not set");
     }

+    if (!term_mode_init()) {
+        term_init_fail("tcgetattr: %s", strerror(errno));
+    }
+
     if (getenv("DTE_FORCE_TERMINFO")) {
         if (term_init_terminfo(term)) {
             return;
         } else {
             term_init_fail("'DTE_FORCE_TERMINFO' set but terminfo not linked");
         }
     }

-    if (!term_mode_init()) {
-        term_init_fail("tcgetattr: %s", strerror(errno));
-    }
-
     switch (get_term_type(term)) {
     case TERM_XTERM:
         terminal = xterm;
         // terminal.repeat_byte = &ecma48_repeat_byte;
         break;
     case TERM_ST:
     case TERM_URXVT:
         terminal = xterm;
         break;
     case TERM_TMUX:
     case TERM_SCREEN:
     case TERM_KITTY:
         terminal = xterm;
         terminal.back_color_erase = false;
         break;
     case TERM_LINUX:
         // Use the default Terminal and just change the control codes
         terminal.control_codes.hide_cursor = xterm.control_codes.hide_cursor;
         terminal.control_codes.show_cursor = xterm.control_codes.show_cursor;
         break;
     case TERM_OTHER:
         if (term_init_terminfo(term)) {
             return;
         }
         break;
     }

     const char *colorterm = getenv("COLORTERM");
     if (colorterm && streq(colorterm, "truecolor")) {
         terminal.color_type = TERM_TRUE_COLOR;
         return;
     }

     if (
         terminal.color_type < TERM_256_COLOR
         && str_has_suffix(term, "256color")
     ) {
         terminal.color_type = TERM_256_COLOR;
     } else if (str_has_suffix(term, "-direct")) {
         terminal.color_type = TERM_TRUE_COLOR;
     }
 }
